# Generated by manage.py generate_test_cases.
from unittest.mock import patch

from django.contrib.contenttypes.models import ContentType

from bloomerp.models.application_field import ApplicationField
from bloomerp.models.definition import (
    BloomerpModelConfig,
    DetailViewSettings,
    FieldLayout,
    LayoutItem,
    LayoutRow,
)
from bloomerp.models.users.user_object_layout_preference import UserObjectLayoutPreference
from bloomerp.tests.base import (
    BaseBloomerpTestCaseWithModels,
    BloomerpModelTestCase,
    ModelScenario,
    ExpectedModelException,
)


class TestUserObjectLayoutPreferenceModel(
    BloomerpModelTestCase,
    BaseBloomerpTestCaseWithModels,
):
    model = UserObjectLayoutPreference

    def get_test_scenarios(self) -> list[ModelScenario[UserObjectLayoutPreference]]:
        return [
            ModelScenario(
                name="Configured object layouts are all materialized and default selected",
                description=(
                    "UC: A model declares multiple detail layouts.\n"
                    "Expected Result: Every layout becomes a user preference and the declared default is selected."
                ),
                create_operation=self.create_configured_preferences,
                create_validators=self.configured_preferences_are_materialized,
            )
        ]

    def create_configured_preferences(self):
        self.content_type = ContentType.objects.get_for_model(self.CustomerModel)
        settings = DetailViewSettings(
            layouts=[
                FieldLayout(
                    name="Compact",
                    is_default=False,
                    rows=[LayoutRow(columns=1, items=[LayoutItem(id="first_name")])],
                ),
                FieldLayout(
                    name="Detailed",
                    rows=[LayoutRow(columns=1, items=[LayoutItem(id="last_name")])],
                ),
            ]
        )
        with patch.object(
            self.CustomerModel,
            "bloomerp_config",
            BloomerpModelConfig(detail_view_settings=settings),
            create=True,
        ):
            return UserObjectLayoutPreference.create_default_for_user(
                self.admin_user,
                content_type_id=self.content_type.pk,
            )

    def configured_preferences_are_materialized(self, selected):
        preferences = list(
            UserObjectLayoutPreference.objects.filter(
                user=self.admin_user,
                content_type=self.content_type,
            ).order_by("pk")
        )
        first_name = ApplicationField.get_by_field(self.CustomerModel, "first_name")
        last_name = ApplicationField.get_by_field(self.CustomerModel, "last_name")
        return (
            [preference.name for preference in preferences] == ["Compact", "Detailed"]
            and not preferences[0].selected
            and preferences[1].selected
            and selected == preferences[1]
            and preferences[0].layout["rows"][0]["items"][0]["id"] == first_name.pk
            and preferences[1].layout["rows"][0]["items"][0]["id"] == last_name.pk
        )
